    {
      "cell_type": "code",
      "source": [
        "%%R\n",
        "set.seed(123)\n",
        "\n",
        "sample_index <- sample(1:nrow(model_data), 0.8*nrow(model_data))\n",
        "\n",
        "train <- model_data[sample_index, ]\n",
        "test <- model_data[-sample_index, ]"
